      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिससे आप details जो sellers होते हैं वो..."
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "तो यहां पे जो sellers होते हैं वो वो कहीं के भी होते हैं like अलग-अलग sellers होते हैं तो तो फिर सबके prices अलग होंगे।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बिल्कुल अलग-अलग sellers होते हैं और सभी के prices अलग हो सकते हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आप seller से details और price discuss कर सकते हैं।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "तो जैसे मैंने जो भी select किया होगा वहां पे और मैं बात करूंगी तो फिर वो उसी seller से बात होगा जिसका मैंने select किया है।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आप जिस seller को select करते हैं सबसे पहले उसी से connect किया जाएगा।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "सात।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "इसमें और भी sellers की भी details WhatsApp पे मिल जाएंगी ताकि आप compare कर सकें।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "Okay तो ये सब मुझे कैसे मिलेगा?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपको seller की details और contact WhatsApp पे भेज दी जाएंगी।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "आप उनसे सीधा बात करके price और details जान सकते हैं।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "Okay okay तो ये मुझे WhatsApp पे अभी आप send कर दोगे?"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "जी हां।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपकी details confirm होते ही seller की जानकारी और बाकी details आपको WhatsApp पे भेज दी जाएंगी।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "हम्म तो मैंने तो आपको इससे पहले वाले call पे बता दिया था मेरी details।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "अभी मुझे system में आपकी details confirm नहीं दिख रही हैं।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "बस जल्दी से confirm कर दीजिए ताकि मैं आगे बढ़ सकूं।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "Okay, अह सब कुछ confirm करना पड़ेगा?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "नहीं अभी call पे ही details confirm कर दीजिए WhatsApp पे सिर्फ seller की जानकारी भेजी जाएगी।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "हाँ तो पूछिए।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "आपको easel wooden stand के लिए कौन सा easel type चाहिए folding, meaning या कुछ और?"
